-- P33 structural administration. Aliases/merge links never participate in authorization.
create table public.organization_control(term_id uuid primary key references public.terms(id),work_item_id uuid not null unique references public.announcements(work_item_id));
create table public.unit_aliases(term_id uuid not null references public.terms(id),alias text not null,unit_id uuid not null references public.org_units(id),primary key(term_id,alias));
create table public.unit_links(source_unit_id uuid primary key references public.org_units(id),target_unit_id uuid not null references public.org_units(id),created_at timestamptz not null default statement_timestamp(),check(source_unit_id<>target_unit_id));
create table public.organization_changes(control_id uuid not null references public.organization_control(work_item_id),version integer not null,action text not null,target_id uuid,metadata jsonb not null,actor_id uuid not null references auth.users(id),reason text not null,created_at timestamptz not null default statement_timestamp(),primary key(control_id,version));
create table public.work_unit_origins(work_item_id uuid primary key references public.work_items(id),unit_id uuid references public.org_units(id));
do $$declare t text;begin foreach t in array array['organization_control','unit_aliases','unit_links','organization_changes','work_unit_origins']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create trigger immutable_unit_aliases before update or delete on public.unit_aliases for each row execute function app_private.request_history_guard();
create trigger immutable_unit_links before update or delete on public.unit_links for each row execute function app_private.request_history_guard();
create trigger immutable_organization_changes before update or delete on public.organization_changes for each row execute function app_private.request_history_guard();
create trigger immutable_work_unit_origins before update or delete on public.work_unit_origins for each row execute function app_private.request_history_guard();
create function app_private.organization_actor(p_term uuid,p_write boolean default false)returns public.term_memberships language plpgsql stable security definer set search_path='' as $$declare m public.term_memberships;begin m:=app_private.request_actor(p_term,p_write);if not public.has_capability(p_term,'admin.configure')or not public.has_capability(p_term,'roles.manage')then raise exception using errcode='42501',message='command_permission_denied';end if;return m;end$$;
create function app_private.organization_obligations(p_term uuid,p_unit uuid default null,p_membership uuid default null)returns setof public.work_items language sql stable security definer set search_path='' as $$
 select distinct w.*from public.work_items w join public.status_definitions s on s.id=w.status_id left join public.requests r on r.work_item_id=w.id left join public.tasks task on task.work_item_id=w.id
 where w.term_id=p_term and w.archived_at is null and s.semantic_category not in('completed','rejected','cancelled')and not exists(select 1 from public.organization_control c where c.work_item_id=w.id)and(
 (p_unit is not null and(w.lead_unit_id=p_unit or r.receiving_unit_id=p_unit or task.assigned_unit_id=p_unit or exists(select 1 from public.synergy_agreements a where a.parent_work_item_id=w.id and(a.requester_unit_id=p_unit or a.receiver_unit_id=p_unit)and a.state in('proposed','countered','accepted'))or exists(select 1 from public.handoffs h where(h.source_task_id=w.id or h.next_task_id=w.id)and h.receiver_unit_id=p_unit and h.state not in('declined','cancelled'))))or
 (p_membership is not null and(w.owner_member_id=(select member_id from public.term_memberships where id=p_membership)or task.assignee_id=(select member_id from public.term_memberships where id=p_membership)or exists(select 1 from public.approval_assignments a join public.workflow_instances x on x.id=a.instance_id where a.request_id=w.id and a.reviewer_id=p_membership and x.state in('paused','active','needs_revision')and x.generation=a.generation))))
$$;
create function app_private.organization_fingerprint(p_term uuid,p_action text,p_values jsonb)returns text language sql stable security definer set search_path='' as $$
 select encode(sha256(convert_to(jsonb_build_array(p_action,p_values,
 (select coalesce(jsonb_agg(to_jsonb(u)order by u.id),'[]')from public.org_units u where term_id=p_term),
 (select coalesce(jsonb_agg(to_jsonb(m)order by m.id),'[]')from public.term_memberships m where term_id=p_term),
 (select coalesce(jsonb_agg(jsonb_build_array(m.id,m.version,m.account_state,m.display_name)order by m.id),'[]')from public.members m where exists(select 1 from public.term_memberships t where t.term_id=p_term and t.member_id=m.id)),
 (select coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('effective',d.status='active'and d.effective_from<=statement_timestamp()and d.effective_to>statement_timestamp())order by d.id),'[]')from public.unit_memberships d where term_id=p_term),
 (select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('effective',a.status='active'and a.effective_from<=statement_timestamp()and a.effective_to>statement_timestamp())order by a.id),'[]')from public.role_assignments a where term_id=p_term),
 (select coalesce(jsonb_agg(to_jsonb(p)order by p.id),'[]')from public.role_permissions p where term_id=p_term),
 (select coalesce(jsonb_agg(to_jsonb(r)order by r.id),'[]')from public.roles r where term_id=p_term),
 (select coalesce(jsonb_agg(jsonb_build_array(a.id,a.version,a.state)order by a.id),'[]')from public.synergy_agreements a where term_id=p_term),
 (select coalesce(jsonb_agg(jsonb_build_array(h.id,h.version,h.state)order by h.id),'[]')from public.handoffs h where term_id=p_term),
 (select coalesce(jsonb_agg(jsonb_build_array(w.id,w.version,w.owner_member_id,w.lead_unit_id,w.status_id,w.archived_at)order by w.id),'[]')from public.work_items w where term_id=p_term),
 (select coalesce(jsonb_agg(jsonb_build_array(x.id,x.state,x.generation)order by x.id),'[]')from public.workflow_instances x where term_id=p_term),
 (select coalesce(jsonb_agg(jsonb_build_array(t.id,t.live_enabled,t.receiving_unit_id,t.primary_contact_id,t.backup_contact_id)order by t.id),'[]')from public.request_types t where term_id=p_term)
 )::text,'UTF8')),'hex')
$$;
create function public.preview_organization_change(p_term_id uuid,p_action text,p_values jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$
declare m public.term_memberships;u public.org_units;target public.org_units;tm public.term_memberships;dep public.unit_memberships;w public.work_items;d public.deliverables;change_id uuid;unit uuid;member uuid;allowed text[];blocked boolean:=false;obligations jsonb:='[]';row public.work_items;reviewers jsonb;deltas jsonb;v integer;previous jsonb:='{}';changes jsonb;begin
 m:=app_private.organization_actor(p_term_id);allowed:=case p_action when 'unit_save'then array['id','code','name','delivery','review']when 'unit_archive'then array['id']when 'unit_merge'then array['id','targetId']when 'roster_add'then array['email','name','joinedAt','endsAt']when 'roster_edit'then array['id','name','status','joinedAt','endsAt']when 'deployment_save'then array['id','memberId','unitId','type','from','to','state']when 'work_reassign'then array['id','unitId','ownerId','workVersion']else null end;
 if allowed is null or not app_private.definition_keys(p_values,allowed)then raise exception using errcode='22023',message='command_validation_failed';end if;
 change_id:=nullif(p_values->>'id','')::uuid;
 if p_action like 'unit_%'and change_id is not null then select *into u from public.org_units where org_units.id=change_id and term_id=p_term_id and archived_at is null;if not found then raise exception using errcode='42501',message='command_permission_denied';end if;unit:=u.id;end if;
 if p_action='unit_save'then
 if not app_private.definition_text(p_values->'name',200)or not app_private.definition_text(p_values->'code',40)or(p_values->>'code')!~'^[A-Z][A-Z0-9_-]{0,39}$'or jsonb_typeof(p_values->'delivery')is distinct from 'boolean'or jsonb_typeof(p_values->'review')is distinct from 'boolean'then raise exception using errcode='22023',message='command_validation_failed';end if;
 if change_id is not null and((u.delivery_committee and not(p_values->>'delivery')::boolean)or(u.review_service and not(p_values->>'review')::boolean))then blocked:=exists(select 1 from app_private.organization_obligations(p_term_id,unit))or exists(select 1 from public.request_types rt where rt.term_id=p_term_id and rt.receiving_unit_id=unit and rt.live_enabled and rt.archived_at is null);end if;
 elsif p_action in('unit_archive','unit_merge')then
 if unit is null then raise exception using errcode='22023',message='command_validation_failed';end if;
 blocked:=exists(select 1 from app_private.organization_obligations(p_term_id,unit))or exists(select 1 from public.request_types t where t.term_id=p_term_id and t.receiving_unit_id=unit and t.live_enabled and t.archived_at is null);
 if p_action='unit_merge'then select *into target from public.org_units where org_units.id=(p_values->>'targetId')::uuid and term_id=p_term_id and archived_at is null and org_units.id<>unit;if not found then raise exception using errcode='22023',message='command_validation_failed';end if;end if;
 elsif p_action in('roster_add','roster_edit')then
 if not app_private.definition_text(p_values->'name',200)or(p_values->>'joinedAt')is null or(p_values->>'endsAt')is null or not isfinite((p_values->>'joinedAt')::timestamptz)or not isfinite((p_values->>'endsAt')::timestamptz)or(p_values->>'joinedAt')::timestamptz>=(p_values->>'endsAt')::timestamptz then raise exception using errcode='22023',message='command_validation_failed';end if;
 if p_action='roster_add'then if jsonb_typeof(p_values->'email')is distinct from 'string'or lower(btrim(p_values->>'email'))!~'^[^[:space:]@]+@student[.]ateneo[.]edu$'then raise exception using errcode='22023',message='command_validation_failed';end if;
 else select *into tm from public.term_memberships where term_memberships.id=change_id and term_id=p_term_id and membership_kind='core';if not found or(p_values->>'status')is null or(p_values->>'status')not in('active','suspended')then raise exception using errcode='22023',message='command_validation_failed';end if;member:=tm.id;
 if(p_values->>'status')<>'active'or(p_values->>'joinedAt')::timestamptz>statement_timestamp()or(p_values->>'endsAt')::timestamptz<=statement_timestamp()or(p_values->>'endsAt')::timestamptz<tm.ends_at or(p_values->>'joinedAt')::timestamptz>tm.joined_at then
 blocked:=exists(select 1 from app_private.organization_obligations(p_term_id,null,member))or member=m.id or exists(select 1 from public.role_assignments a join public.role_permissions p on p.role_id=a.role_id where a.term_membership_id=member and a.status='active'and a.effective_to>statement_timestamp()and p.capability in('admin.configure','roles.manage'))or exists(select 1 from public.request_types t where t.term_id=p_term_id and t.live_enabled and t.archived_at is null and member in(t.primary_contact_id,t.backup_contact_id));end if;end if;
 elsif p_action='deployment_save'then
 unit:=(p_values->>'unitId')::uuid;member:=(p_values->>'memberId')::uuid;select *into tm from public.term_memberships where term_memberships.id=member and term_id=p_term_id and membership_kind='core'and status='active'and joined_at<=statement_timestamp()and ends_at>statement_timestamp();
 if not found or not exists(select 1 from public.members where members.id=tm.member_id and account_state='active')or not exists(select 1 from public.org_units where org_units.id=unit and term_id=p_term_id and archived_at is null)or(p_values->>'type')is null or(p_values->>'type')not in('member','head','associate','primary_contact','backup_contact')or(p_values->>'state')is null or(p_values->>'state')not in('active','revoked')or(p_values->>'from')is null or(p_values->>'to')is null or not isfinite((p_values->>'from')::timestamptz)or not isfinite((p_values->>'to')::timestamptz)or(p_values->>'from')::timestamptz>=(p_values->>'to')::timestamptz or(p_values->>'from')::timestamptz<tm.joined_at or(p_values->>'to')::timestamptz>tm.ends_at then raise exception using errcode='22023',message='command_validation_failed';end if;
 if change_id is not null then select *into dep from public.unit_memberships where unit_memberships.id=change_id and term_id=p_term_id;if not found or(dep.term_membership_id,dep.unit_id,dep.deployment_type)is distinct from(member,unit,p_values->>'type')then raise exception using errcode='22023',message='command_validation_failed';end if;
 if p_values->>'state'='revoked'or(p_values->>'from')::timestamptz>statement_timestamp()or(p_values->>'to')::timestamptz<dep.effective_to then blocked:=exists(select 1 from app_private.organization_obligations(p_term_id,unit,member))or exists(select 1 from public.request_types t where t.term_id=p_term_id and t.live_enabled and t.archived_at is null and member in(t.primary_contact_id,t.backup_contact_id));end if;end if;
 elsif p_action='work_reassign'then
 select *into w from public.work_items where work_items.id=change_id and term_id=p_term_id and kind='deliverable'and classification='ordinary'and archived_at is null;
 if not found or not public.can_access_work(w.id,'edit')then raise exception using errcode='42501',message='command_permission_denied';end if;
 unit:=w.lead_unit_id;select *into d from public.deliverables where work_item_id=w.id;select *into target from public.org_units where org_units.id=(p_values->>'unitId')::uuid and term_id=p_term_id and archived_at is null;
 if target.id is null or not app_private.manage_deliverable(p_term_id,unit)or not app_private.manage_deliverable(p_term_id,target.id)or not exists(select 1 from public.term_memberships mm join public.members person on person.id=mm.member_id where mm.term_id=p_term_id and mm.member_id=(p_values->>'ownerId')::uuid and mm.status='active'and mm.membership_kind='core'and mm.joined_at<=statement_timestamp()and mm.ends_at>statement_timestamp()and person.account_state='active')then raise exception using errcode='42501',message='command_permission_denied';end if;
 if w.version is distinct from(p_values->>'workVersion')::integer then raise exception using errcode='40001',message='command_stale_version';end if;
 blocked:=d.workflow_state not in('proposed','draft','in_progress')or d.finance_required or d.publicity_required or d.work_types<>array['operations']or exists(select 1 from public.finance_revisions where related_deliverable_id=w.id)or exists(select 1 from public.publicity_reviews where related_deliverable_id=w.id)or exists(select 1 from public.work_items where parent_work_item_id=w.id)or exists(select 1 from public.synergy_agreements where parent_work_item_id=w.id);
 end if;
 if unit is not null or member is not null then for row in select *from app_private.organization_obligations(p_term_id,unit,member)loop if public.can_access_work(row.id,'detail')then obligations:=obligations||jsonb_build_array(jsonb_build_object('id',row.id,'title',case when row.classification='ordinary'then row.title else 'Restricted work — resolve in its own authorized workflow'end,'href',case row.kind when 'deliverable'then '/deliverables/'when 'task'then '/tasks/'else null end||row.id));end if;end loop;end if;
 select coalesce(jsonb_agg(jsonb_build_object('memberId',a.term_membership_id,'name',person.display_name,'capability',p.capability,'unitId',a.unit_id)order by a.id,p.capability),'[]')into reviewers from public.role_assignments a join public.role_permissions p on p.role_id=a.role_id and p.allowed_scope=a.scope_type join public.roles role on role.id=a.role_id and role.state='active'join public.term_memberships mm on mm.id=a.term_membership_id join public.members person on person.id=mm.member_id where a.term_id=p_term_id and a.status='active'and a.effective_from<=statement_timestamp()and a.effective_to>statement_timestamp()and(unit is null or a.unit_id=unit)and(member is null or a.term_membership_id=member);
 deltas:=jsonb_build_object('transferredRoles',0,'transferredRecordGrants',0,'transferredDeployments',0,'affectedUnitId',unit,'targetUnitId',target.id,'targetOwnerId',p_values->>'ownerId','potentialExistingCapabilities',reviewers,'targetCapabilities',coalesce((select jsonb_agg(jsonb_build_object('memberId',a.term_membership_id,'capability',rp.capability,'unitId',a.unit_id))from public.role_assignments a join public.role_permissions rp on rp.role_id=a.role_id and rp.allowed_scope=a.scope_type join public.roles rr on rr.id=a.role_id and rr.state='active'where a.term_id=p_term_id and a.unit_id=coalesce(target.id,unit)and a.status='active'and a.effective_from<=statement_timestamp()and a.effective_to>statement_timestamp()and(member is null or a.term_membership_id=member)),'[]'),'message',case when p_action='unit_merge'then 'Source unit deployments/capabilities cease to be effective. No target deployment, role, sensitive case or record grant is copied.'when p_action='deployment_save'then 'Dated deployment may activate existing roles in this exact unit. No new role assignment is created.'when p_action='work_reassign'then 'Only this permitted ordinary deliverable changes current owner/routing; target-unit existing scope may become effective. Old record grants remain unchanged.'else 'No roles or record grants are created or transferred.'end);
 previous:=case when p_action like 'unit_%'then jsonb_build_object('code',u.code,'name',u.name,'delivery',u.delivery_committee,'review',u.review_service,'targetId',null)when p_action='roster_edit'then jsonb_build_object('name',(select display_name from public.members where id=tm.member_id),'status',tm.status,'joinedAt',tm.joined_at,'endsAt',tm.ends_at)when p_action='deployment_save'then jsonb_build_object('memberId',dep.term_membership_id,'unitId',dep.unit_id,'type',dep.deployment_type,'state',dep.status,'from',dep.effective_from,'to',dep.effective_to)when p_action='work_reassign'then jsonb_build_object('unitId',w.lead_unit_id,'ownerId',w.owner_member_id,'workVersion',w.version)else '{}'::jsonb end;
 select coalesce(jsonb_agg(jsonb_build_object('field',e.key,'before',previous->e.key,'after',e.value)order by e.key),'[]')into changes from jsonb_each(p_values)e where e.key<>'id'and previous->e.key is distinct from e.value;
 select coalesce(wi.version,0)into v from public.organization_control c join public.work_items wi on wi.id=c.work_item_id where c.term_id=p_term_id;
 return jsonb_build_object('changes',changes,'version',coalesce(v,0),'fingerprint',app_private.organization_fingerprint(p_term_id,p_action,p_values),'blocked',blocked,'message',case when blocked then 'Blocked: resolve active ownership, reviewer/service contacts or protected scope through the authorized workflow before publishing this change.'else 'Review the explicit access effect, then publish this structural change.'end,'openWork',obligations,'activeReviewers',reviewers,'accessDelta',deltas);
 end$$;
create function app_private.organization_alias(p_term uuid,p_alias text,p_unit uuid)returns void language plpgsql set search_path='' as $$begin
 insert into public.unit_aliases values(p_term,lower(btrim(p_alias)),p_unit)on conflict(term_id,alias)do nothing;if not exists(select 1 from public.unit_aliases where term_id=p_term and alias=lower(btrim(p_alias))and unit_id=p_unit)then raise exception using errcode='22023',message='unit_alias_unavailable';end if;end$$;
create function public.publish_organization_change(p_term_id uuid,p_action text,p_values jsonb,p_expected_version integer,p_fingerprint text,p_reason text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare m public.term_memberships;w public.work_items;u public.org_units;tm public.term_memberships;dep public.unit_memberships;person public.members;control uuid;status uuid;payload jsonb;result jsonb;impact jsonb;change_id uuid;metadata jsonb;dw public.work_items;d public.deliverables;begin
 perform app_private.readiness_lock(p_term_id);m:=app_private.organization_actor(p_term_id,true);payload:=jsonb_build_array(p_term_id,p_action,p_values,p_expected_version,p_fingerprint,p_reason);result:=app_private.begin_work_command('publish_organization_change',p_request_id,payload);if result is not null then return result;end if;
 if p_reason is null or length(btrim(p_reason))not between 1 and 1000 then raise exception using errcode='22023',message='command_validation_failed';end if;
 impact:=public.preview_organization_change(p_term_id,p_action,p_values);
 if(impact->>'version')::integer is distinct from p_expected_version or impact->>'fingerprint'is distinct from p_fingerprint then raise exception using errcode='40001',message='command_stale_version';end if;
 if(impact->>'blocked')::boolean then raise exception using errcode='55000',message='command_dependency_blocked';end if;
 select work_item_id into control from public.organization_control where term_id=p_term_id;
 if control is null then
 insert into public.status_definitions(organization_id,term_id,resource_kind,stable_key,semantic_category,label)values(m.organization_id,p_term_id,'announcement','draft','draft','Draft')on conflict(term_id,resource_kind,stable_key)do nothing;select id into status from public.status_definitions where term_id=p_term_id and resource_kind='announcement'and stable_key='draft';
 insert into public.work_items(organization_id,term_id,kind,title,classification,owner_member_id,owner_display_name,status_id)values(m.organization_id,p_term_id,'announcement','Organization control','restricted',m.member_id,(select display_name from public.members where members.id=m.member_id),status)returning *into w;
 insert into public.announcements(work_item_id,organization_id,term_id)values(w.id,w.organization_id,w.term_id);insert into public.organization_control values(p_term_id,w.id);
 else update public.work_items set updated_at=statement_timestamp()where work_items.id=control returning *into w;end if;
 change_id:=nullif(p_values->>'id','')::uuid;metadata:=jsonb_build_object('fields',(select jsonb_agg(key)from jsonb_object_keys(p_values)key),'changes',coalesce((select jsonb_agg(e.value)from jsonb_array_elements(impact->'changes')e where e.value->>'field'<>'email'),'[]'::jsonb));
 if p_action='unit_save'then
 if change_id is null then insert into public.org_units(organization_id,term_id,code,name,delivery_committee,review_service)values(m.organization_id,p_term_id,p_values->>'code',btrim(p_values->>'name'),(p_values->>'delivery')::boolean,(p_values->>'review')::boolean)returning *into u;change_id:=u.id;
 else select *into u from public.org_units where org_units.id=change_id for update;perform app_private.organization_alias(p_term_id,u.code,change_id);perform app_private.organization_alias(p_term_id,u.name,change_id);metadata:=metadata||jsonb_build_object('previousCode',u.code,'previousName',u.name);update public.org_units set code=p_values->>'code',name=btrim(p_values->>'name'),delivery_committee=(p_values->>'delivery')::boolean,review_service=(p_values->>'review')::boolean where org_units.id=change_id returning *into u;end if;
 perform app_private.organization_alias(p_term_id,u.code,change_id);perform app_private.organization_alias(p_term_id,u.name,change_id);metadata:=metadata||jsonb_build_object('code',u.code,'name',u.name);
 elsif p_action in('unit_archive','unit_merge')then
 if p_action='unit_merge'then insert into public.unit_links(source_unit_id,target_unit_id)values(change_id,(p_values->>'targetId')::uuid);end if;
 select *into u from public.org_units where org_units.id=change_id;perform app_private.organization_alias(p_term_id,u.code,change_id);perform app_private.organization_alias(p_term_id,u.name,change_id);update public.org_units set archived_at=statement_timestamp()where org_units.id=change_id;metadata:=metadata||jsonb_build_object('targetUnitId',p_values->>'targetId','noGrantTransfer',true);
 elsif p_action='roster_add'then
 select *into person from public.members where organization_id=m.organization_id and normalized_email=lower(btrim(p_values->>'email'));
 if person.id is null then insert into public.members(organization_id,email,display_name,account_state)values(m.organization_id,lower(btrim(p_values->>'email')),btrim(p_values->>'name'),'active')returning *into person;
 elsif person.account_state<>'active'then raise exception using errcode='55000',message='command_dependency_blocked';end if;
 insert into public.term_memberships(organization_id,term_id,member_id,status,joined_at,ends_at)values(m.organization_id,p_term_id,person.id,'active',(p_values->>'joinedAt')::timestamptz,(p_values->>'endsAt')::timestamptz)returning *into tm;change_id:=tm.id;
 elsif p_action='roster_edit'then
 select *into tm from public.term_memberships where term_memberships.id=change_id;update public.members set display_name=btrim(p_values->>'name')where members.id=tm.member_id;
 update public.term_memberships set status=p_values->>'status',joined_at=(p_values->>'joinedAt')::timestamptz,ends_at=(p_values->>'endsAt')::timestamptz where term_memberships.id=change_id;
 elsif p_action='deployment_save'then
 if change_id is null then insert into public.unit_memberships(organization_id,term_id,term_membership_id,unit_id,deployment_type,status,effective_from,effective_to,approved_by)values(m.organization_id,p_term_id,(p_values->>'memberId')::uuid,(p_values->>'unitId')::uuid,p_values->>'type',p_values->>'state',(p_values->>'from')::timestamptz,(p_values->>'to')::timestamptz,m.id)returning unit_memberships.id into change_id;
 else update public.unit_memberships set status=p_values->>'state',effective_from=(p_values->>'from')::timestamptz,effective_to=(p_values->>'to')::timestamptz,approved_by=m.id where unit_memberships.id=change_id;end if;
 elsif p_action='work_reassign'then
 select *into dw from public.work_items where work_items.id=change_id for update;select *into d from public.deliverables where work_item_id=change_id;
 insert into public.work_unit_origins values(change_id,dw.lead_unit_id)on conflict(work_item_id)do nothing;
 perform public.update_deliverable(change_id,jsonb_build_object('title',dw.title,'summary',dw.safe_summary,'body',d.body,'ownerId',p_values->>'ownerId','leadUnitId',p_values->>'unitId','phase',d.phase_key,'outcome',d.outcome,'criteria',d.acceptance_criteria,'dueOn',dw.due_on,'dueAt',dw.due_at,'classification',dw.classification,'reason',p_reason),(p_values->>'workVersion')::integer,p_request_id);
 metadata:=metadata||jsonb_build_object('previousUnitId',dw.lead_unit_id,'targetUnitId',p_values->>'unitId','previousOwnerId',dw.owner_member_id,'targetOwnerId',p_values->>'ownerId');
 end if;
 insert into public.organization_changes(control_id,version,action,target_id,metadata,actor_id,reason)values(w.id,w.version,p_action,change_id,metadata,auth.uid(),btrim(p_reason));
 return app_private.finish_work_command(w,'publish_organization_change',p_request_id,payload,jsonb_build_object('id',change_id,'version',w.version),'["organization_structure"]');end$$;
create function public.read_organization(p_term_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare m public.term_memberships;begin m:=app_private.organization_actor(p_term_id);return jsonb_build_object(
 'version',coalesce((select w.version from public.organization_control c join public.work_items w on w.id=c.work_item_id where c.term_id=p_term_id),0),
 'canPublish',exists(select 1 from public.terms where id=p_term_id and state='active'),
 'units',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'code',u.code,'name',u.name,'delivery',u.delivery_committee,'review',u.review_service,'archivedAt',u.archived_at,'version',u.version)order by u.name,u.id)from public.org_units u where term_id=p_term_id),'[]'),
 'aliases',coalesce((select jsonb_agg(jsonb_build_object('alias',alias,'unitId',unit_id)order by alias)from public.unit_aliases where term_id=p_term_id),'[]'),
 'links',coalesce((select jsonb_agg(jsonb_build_object('sourceId',l.source_unit_id,'targetId',l.target_unit_id))from public.unit_links l join public.org_units u on u.id=l.source_unit_id where term_id=p_term_id),'[]'),
 'members',coalesce((select jsonb_agg(jsonb_build_object('id',tm.id,'memberId',tm.member_id,'name',p.display_name,'email',p.normalized_email,'state',tm.status,'accountState',p.account_state,'joinedAt',tm.joined_at,'endsAt',tm.ends_at,'version',tm.version)order by p.display_name,tm.id)from public.term_memberships tm join public.members p on p.id=tm.member_id where tm.term_id=p_term_id and tm.membership_kind='core'),'[]'),
 'deployments',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'memberId',d.term_membership_id,'unitId',d.unit_id,'type',d.deployment_type,'state',d.status,'from',d.effective_from,'to',d.effective_to,'version',d.version)order by d.id)from public.unit_memberships d where term_id=p_term_id),'[]'),
 'work',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'title',w.title,'version',w.version,'unitId',w.lead_unit_id,'ownerId',w.owner_member_id,'originUnitId',case when o.work_item_id is null then w.lead_unit_id else o.unit_id end)order by w.id)from public.work_items w left join public.work_unit_origins o on o.work_item_id=w.id where w.term_id=p_term_id and w.kind='deliverable'and w.classification='ordinary'and w.archived_at is null and public.can_access_work(w.id,'edit')),'[]'),
 'history',coalesce((select jsonb_agg(jsonb_build_object('version',c.version,'action',c.action,'targetId',c.target_id,'at',c.created_at,'reason',c.reason)order by c.version desc)from public.organization_changes c join public.organization_control o on o.work_item_id=c.control_id where o.term_id=p_term_id),'[]')
 );end$$;
revoke all on function app_private.organization_actor(uuid,boolean),app_private.organization_obligations(uuid,uuid,uuid),app_private.organization_fingerprint(uuid,text,jsonb),app_private.organization_alias(uuid,text,uuid)from public,anon,authenticated,service_role;
revoke all on function public.read_organization(uuid),public.preview_organization_change(uuid,text,jsonb),public.publish_organization_change(uuid,text,jsonb,integer,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.read_organization(uuid),public.preview_organization_change(uuid,text,jsonb),public.publish_organization_change(uuid,text,jsonb,integer,text,text,uuid)to authenticated;
